mapper.select:
select   
and c.certification_id=#{certificationId}
and exists(select 1 from cm_collection_item ci join cm_question_revision qr on qr.id=ci.question_revision_id join cm_question q on q.id=qr.question_id where ci.collection_revision_id=r.id and q.exam_subject_id=#{subjectId})
and r.collection_name ilike concat('%',#{keyword},'%')
order by r.published_time desc,c.id desc limit #{limit} offset #{offset}
